content.text:
The evidence points to one fault: CPU saturation in ts-travel-service. Its effect reaches the user through route-plan, travel-plan, preserve and the dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'abn' src, metric, round(avg(value),3) av, round(max(value),3) mx FROM abnormal_metrics WHERE attr_k8s_deployment_name='ts-travel-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization','k8s.pod.cpu.usage') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, round(avg(value),3), round(max(value),3) FROM normal_metrics WHERE attr_k8s_deployment_name='ts-travel-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization','k8s.pod.cpu.usage') GROUP BY 1,2", "claim": "Travel-service pod CPU usage rose from about 0.18 to 0.97 and limit utilization to 0.95, pinning the container."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name IN ('TravelController.queryInfo','POST /api/v1/travelservice/trips/left') GROUP BY 1,2", "claim": "Travel-service queryInfo p95 rose to about 1437 ms and trips/left server p95 to about 1440 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-travel-service' AND span_name IN ('TravelController.queryInfo','POST /api/v1/travelservice/trips/left') GROUP BY 1,2", "claim": "Normal period: travel-service queryInfo p95 about 462 ms and trips/left about 464 ms."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "WITH t AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name='RoutePlanController.getQuickestRoutes' ORDER BY duration DESC LIMIT 1) SELECT s.service_name, s.span_name, s.attr_span_kind kind, round(s.duration/1e6,1) ms, s.attr_status_code, s.attr_http_response_status_code code FROM abnormal_traces s JOIN t USING(trace_id) WHERE s.service_name IN ('ts-route-plan-service','ts-travel-service') ORDER BY s.time", "claim": "Route-plan's client call to travel-service took about 936 ms, matching travel's 934 ms server span."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, s.attr_http_response_status_code code, s.attr_status_code, count(*) n, round(avg(s.duration)/1e6,1) avg_ms FROM abnormal_traces s WHERE s.service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND (s.attr_status_code='Error' OR s.attr_http_response_status_code >= 400) GROUP BY ALL ORDER BY n DESC", "claim": "Route-plan returned 500/503 errors on quickestRoute and cheapestRoute; travel-plan saw those failures."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,2", "claim": "Travel-plan and ui-dashboard server spans show multi-second p95 latency and error spans in the abnormal period."}]},
    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, s.attr_http_response_status_code code, count(*) n, round(avg(s.duration)/1e6,1) avg_ms FROM abnormal_traces s WHERE s.service_name='ts-ui-dashboard' AND s.span_name='POST /api/v1/travelservice/trips/left' AND s.attr_status_code='Error' GROUP BY ALL", "claim": "Ui-dashboard's calls to travel-service trips/left failed with 503 after multi-second waits."}]}
  ]
}
```

